## solutions

#### recursive

```cpp
#include <vector>
#include <string>

std::vector<std::vector<std::string>> permutations(std::vector<std::string> elements) {
  if (elements.size() == 0) {
    return std::vector<std::vector<std::string>> {{}};
  }

  std::string el = elements[0];

  std::vector<std::vector<std::string>> permsWithout = permutations(std::vector<std::string>(elements.begin() + 1, elements.end()));

  std::vector<std::vector<std::string>> result;

  for (std::vector<std::string> without : permsWithout) {
    for (int i = 0; i <= without.size(); i += 1) {
      std::vector<std::string> with = std::vector<std::string>(without.begin(), without.end());
      with.insert(with.begin() + i, el);
      result.push_back(with);
    }
  }

  return result;
}
```

- n = length of items vector
- Time: ~O(n!)
- Space: ~O(n!)
